import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 엑셀 파일은 첫 줄이 머리글이고 칸은 탭으로 나뉜 글자로 전달된다 (엑셀 복사 형태).
const TARGET_HR_INFO = '인사정보';
const TARGET_HR_CARD = '인사기록카드';
// 가정: 인사정보 양식의 칸 순서와 이름
const HR_INFO_HEADER = ['사번', '성명', '부서코드', '이메일', '휴대전화번호', '재직구분', '입사일', '퇴직일'];
const DATE_PATTERN = /^\d{4}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])$/;
const EMPLOYMENT_STATUSES = ['재직', '퇴직'];

interface ErrorRow {
  rowNumber: number;
  reason: string;
}

@Controller('api/v1')
export class FnSfr01204Controller {
  @Post('/hr-uploads')
  @HttpCode(200)
  async uploadHrExcel(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const data = checks.inputOf(req.body);
    const uploadTarget = data['uploadTarget'];
    const file = data['file'];
    if (typeof uploadTarget !== 'string' || ![TARGET_HR_INFO, TARGET_HR_CARD].includes(uploadTarget)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '업로드 대상 구분을 선택해 주세요.');
    }
    if (typeof file !== 'string' || file.trim() === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '업로드할 파일 내용을 입력해 주세요.');
    }
    if (uploadTarget === TARGET_HR_CARD) {
      // TODO: 인사기록카드 테이블이 입력 스키마에 없어 반영하지 못한다.
      throw new ApiError(422, 'UPLOAD_TEMPLATE_INVALID', '인사기록카드 양식은 아직 처리할 수 없습니다.');
    }
    const lines = file.split(/\r?\n/);
    const header = (lines[0] ?? '').split('\t').map((c) => c.trim());
    if (header.length !== HR_INFO_HEADER.length || header.some((c, i) => c !== HR_INFO_HEADER[i])) {
      throw new ApiError(422, 'UPLOAD_TEMPLATE_INVALID', '업로드 파일이 인사정보 양식과 맞지 않습니다.');
    }
    return transaction(async (db) => {
      const errorRows: ErrorRow[] = [];
      let appliedCount = 0;
      for (let i = 1; i < lines.length; i++) {
        const line = lines[i];
        if (line.trim() === '') {
          continue;
        }
        const rowNumber = i + 1;
        const cells = line.split('\t').map((c) => c.trim());
        if (cells.length > HR_INFO_HEADER.length) {
          errorRows.push({ rowNumber, reason: '칸 수가 양식과 맞지 않습니다.' });
          continue;
        }
        const [employeeNo, name, departmentCode, email, mobilePhone, status, hireDate, retirementDate] =
          HR_INFO_HEADER.map((_, idx) => cells[idx] ?? '');
        if (employeeNo === '' || name === '') {
          errorRows.push({ rowNumber, reason: '사번과 성명은 필수입니다.' });
          continue;
        }
        if (employeeNo.length > 20 || name.length > 100 || email.length > 200 || mobilePhone.length > 20) {
          errorRows.push({ rowNumber, reason: '입력 길이가 허용 범위를 넘었습니다.' });
          continue;
        }
        if (status !== '' && !EMPLOYMENT_STATUSES.includes(status)) {
          errorRows.push({ rowNumber, reason: '재직구분은 재직 또는 퇴직이어야 합니다.' });
          continue;
        }
        if ((hireDate !== '' && !DATE_PATTERN.test(hireDate)) || (retirementDate !== '' && !DATE_PATTERN.test(retirementDate))) {
          errorRows.push({ rowNumber, reason: '날짜는 YYYY-MM-DD 형식이어야 합니다.' });
          continue;
        }
        if (status === '퇴직' && retirementDate === '') {
          errorRows.push({ rowNumber, reason: '퇴직으로 바꾸려면 퇴직일이 필요합니다.' });
          continue;
        }
        const found = await db.query(
          'SELECT employee_id AS "employeeId" FROM employee WHERE employee_no = :employeeNo',
          { employeeNo },
        );
        if (found.length === 0) {
          errorRows.push({ rowNumber, reason: '일치하는 임직원(사번)이 없습니다.' });
          continue;
        }
        let departmentId: string | null = null;
        if (departmentCode !== '') {
          const dept = await db.query(
            'SELECT department_id AS "departmentId" FROM department WHERE department_code = :departmentCode',
            { departmentCode },
          );
          if (dept.length === 0) {
            errorRows.push({ rowNumber, reason: '부서코드에 해당하는 부서가 없습니다.' });
            continue;
          }
          departmentId = String(dept[0]['departmentId']);
        }
        // 빈 칸은 기존 값을 유지한다 (가정).
        await db.execute(
          `UPDATE employee SET
             name = :name,
             department_id = COALESCE(CAST(:departmentId AS bigint), department_id),
             email = COALESCE(:email, email),
             mobile_phone = COALESCE(:mobilePhone, mobile_phone),
             employment_status = COALESCE(:status, employment_status),
             hire_date = COALESCE(CAST(:hireDate AS date), hire_date),
             retirement_date = COALESCE(CAST(:retirementDate AS date), retirement_date),
             updated_at = now()
           WHERE employee_no = :employeeNo`,
          {
            employeeNo,
            name,
            departmentId,
            email: email === '' ? null : email,
            mobilePhone: mobilePhone === '' ? null : mobilePhone,
            status: status === '' ? null : status,
            hireDate: hireDate === '' ? null : hireDate,
            retirementDate: retirementDate === '' ? null : retirementDate,
          },
        );
        appliedCount += 1;
      }
      return { appliedCount, errorRows };
    });
  }
}

