import { useState } from 'react';
import { Band, Badge, DataTable, Drawer, Field, Form, Num, Select, Tiles, TextInput, call } from '../kit';
import type { PageProps, Row } from '../kit';

interface UploadResult {
  appliedCount: number;
  errorRows: Row[];
}

interface HistoryItem extends Row {
  target: string;
  appliedCount: number;
  errorCount: number;
}

export default function FnSfr01204Page({ role, notify }: PageProps) {
  const [open, setOpen] = useState(false);
  const [target, setTarget] = useState('');
  const [file, setFile] = useState('');
  const [result, setResult] = useState<UploadResult | undefined>(undefined);
  const [history, setHistory] = useState<HistoryItem[]>([]);

  const openDrawer = () => {
    setTarget('');
    setFile('');
    setOpen(true);
  };

  const submit = async () => {
    if (target === '') {
      throw new Error('업로드 대상 구분을 선택해 주세요.');
    }
    if (file.trim() === '') {
      throw new Error('엑셀 파일 내용을 입력해 주세요.');
    }
    const res = await call<UploadResult>('POST', '/hr-uploads', role, { uploadTarget: target, file });
    setResult(res);
    setHistory([
      { target, appliedCount: res.appliedCount, errorCount: res.errorRows.length },
      ...history,
    ]);
    notify('업로드를 처리했습니다.');
    setOpen(false);
  };

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>업로드 결과</h2>
        <Tiles
          items={[
            ['정상 반영 건수', <Num value={result ? result.appliedCount : 0} />],
            ['오류 행 건수', <Num value={result ? result.errorRows.length : 0} />],
          ]}
        />
      </section>
      <section className="box span-8">
        <h2>오류 행</h2>
        <Band total={result ? result.errorRows.length : 0}>
          <button type="button" onClick={openDrawer}>엑셀 업로드</button>
        </Band>
        <DataTable
          columns={[
            { key: 'rowNumber', label: '오류 행 번호' },
            { key: 'reason', label: '사유' },
          ]}
          rows={result ? result.errorRows : []}
          empty="오류 행이 없습니다."
        />
      </section>
      <section className="box span-4">
        <h2>최근 업로드</h2>
        <DataTable<HistoryItem>
          columns={[
            { key: 'target', label: '대상', render: (r) => <Badge value={r.target} /> },
            { key: 'appliedCount', label: '반영', render: (r) => <Num value={r.appliedCount} /> },
            { key: 'errorCount', label: '오류', render: (r) => <Num value={r.errorCount} /> },
          ]}
          rows={history}
          empty="업로드 내역이 없습니다."
        />
      </section>
      {open && (
        <Drawer title="인사 엑셀 업로드" onClose={() => setOpen(false)}>
          <Form onSubmit={submit} submit="업로드" note="양식의 머리글 줄부터 칸을 탭으로 나눠 붙여 넣습니다.">
            <Field label="업로드 대상 구분" required>
              <Select
                value={target}
                onChange={setTarget}
                options={[['인사정보', '인사정보'], ['인사기록카드', '인사기록카드']]}
              />
            </Field>
            <Field label="양식에 맞게 작성된 엑셀 파일" required wide>
              <TextInput value={file} onChange={setFile} multiline placeholder="사번, 성명, 부서코드, 이메일, 휴대전화번호, 재직구분, 입사일, 퇴직일" />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
